  connectionId: '',
};
// Temp variables
let startX = 0;
let startY = 0;
const $ = document.querySelector.bind(document);
let screenshot: HTMLElement;
let marquee: HTMLElement;
let boxes: HTMLElement;
let _this: any;
export default defineComponent({
  el: '#app',
  mixins: [helperUtil,
    helperMixin,
    documentUtil,
    poActionsUtil,
    ColorGenerator,
    cache,
    displayFieldLabel,
    amountConversionHelper,
    doc_type_sub_type_Util,
    imageFieldSplitter,
    keyDownHelper,
  ],
  components: {
    
    Loader,
    autoTesting,
    DocumentLock,
    MessageBanner,
    SelectionPopup,
    Classification,
    // InvoiceSaveExport,
    MediFieldsView,
    SplitDocument,
    InvoiceDuplicateLock,
    SubHeader,
    supportForm,
    ErrorDocumentView,
    // DocumentClassification,
    restartClassificationPopup,

    Label,
    CheckBox,
    TextInput,
    MultiCheckBox,
    ExtractedTable,
    TableOfCheckboxes,
    HorizontalSeparator,
    timeSpentTimer,
    keyboardShortcutInfoBtn,
  },
  watch: {
    $route(to, from) {
      if (!to.hasOwnProperty('path') || !from.hasOwnProperty('path')) {
        return;
      }

      const to_route = to.path.split('/');
      const from_route = from.path.split('/');
      // match for same route name
      if (
        to_route.length > 2 &&
        from_route.length > 2 &&
        to_route[1] === from_route[1] &&
        this.get_cached_data_id != this.docId
      ) {
        window.location.reload();
      }
    },
  },
  data() {
    return {
      docId: '',
      contact: this.$t('confirm'),
      showDialog: false,
      showExportDialog: false,
      showArticlePage: false,
      disableSelectionButton: true,
      loading: false,
      // enableExportButton: false,
      magnifyGlass: {} as any,
      allowedDoctypes: allowedDocTypes,
      format_warning_dismiss: {} as any,
      origin_warning_alert: {} as any,
      selection_popup_data: {} as any,
      showSelectionPopupDialog: false,
      amount_fields_confidence_count: 0,
      excluded_fields: ['fields_group'],
      account_block: '',
      error_message: '',
      docStatus: '',
      trigger_document_lock: ref(false),
      isInvoiceDuplicate: ref(false),
      split_document: ref(false),
      showAllButtons: ref(false),
      headerFabIcon: ref(false),
      dropdownModel: ref(false),
      imageLoaded: ref(false),
    };
  },
  beforeRouteLeave: async function (to: any, from: any, next: any) {
    // Before leaving this page, lets first reset everything

    await this.setDataToCache();
    this.removeBordersFromRectangles();
    this.removeAllConnectionLines();
    this.removeExistingConfirmationOverlays();
    this.removeMagnifier();
    notify.dismissAll();

    if (typeof this.format_warning_dismiss === 'function') {
      this.format_warning_dismiss();
    }
    if (typeof this.origin_warning_alert === 'function') {
      this.origin_warning_alert();
    }

    await this.releaseDocLock({ doc_id: this.record.doc_id });
    this.record = {};
    this.page = 1;
    this.resetDocStore(to.fullPath);
    this.resetStoreOnRouteChange();
    next();
  },
  showDialog1: function () {
    setTimeout(() => {
      this.showDialog = true;
    }, 2000);
  },
  beforeMount: function () {
    this.renderComponent = false;
    this.isExtenedPanel = false;
  },
  mounted: function () {
    _this = this;
    this.showLoading();

    this.init();
    this.isDebugFlagHandler();
    this.is_admin = isUserAdmin();

    window.addEventListener('resize', this.windowResize);
    document.body.addEventListener('click', this.mouseClicked, true);

    const splitter__before = $('.img-magnifier-container') as HTMLElement;
    if (splitter__before) {
      splitter__before.addEventListener('scroll', this.handleScroll);
    }

    const splitter__after = $('.q-splitter__after');
    if (splitter__after) {
      splitter__after.addEventListener('scroll', this.handleScroll);
    }

    document.addEventListener(
      'selection_popup_closed',
      this.selectionPopupClosed,
    );
  },
  unmounted: function () {
    window.removeEventListener('resize', this.windowResize);
    document.removeEventListener(
      'selection_popup_closed',
      this.selectionPopupClosed,
    );
    window.removeEventListener('keydown', this.keydownEvent);
    document.removeEventListener(
      'removeSelectedAreaOnImage',
      this.removeSelectedAreaOnImage,
    );

    const splitter__before = $('.img-magnifier-container') as HTMLElement;
    if (splitter__before) {
      splitter__before.removeEventListener('scroll', this.handleScroll);
    }

    const splitter__after = $('.q-splitter__after');
    if (splitter__after) {
      splitter__after.removeEventListener('scroll', this.handleScroll);
    }

    try {
      screenshot = $('.screenshot') as HTMLElement;
      if (screenshot) {
        screenshot.removeEventListener('dblclick', this.dblClickToSelect);
        screenshot.removeEventListener('pointerdown', this.startDrag);
      }
    } catch (err) {
      logError('something went wrong while unmount', err);
    }
  },
  methods: {
    downloadFile() {
      downloadDocumentFile(this.docId, this.record.filename, this.tokenQueryParam, '.pdf');
    },
    toggleSupportMenu() {
      if (this.current_menu_data == '') {
        this.toggleMenu();
        this.current_menu_data = 'support';
      } else if (this.current_menu_data == 'support') {
        this.current_menu_data = 'pages';
      } else if (this.current_menu_data == 'pages') {
        this.current_menu_data = 'support';
        logInfo(this.current_menu_data);
      }
    },
    async init() {
      this.docId = this.$route.params.id as string;
      this.setAppType();

      await this.getInvoiceDataByDocId(this.docId);
      if (
        !this.record ||
        Object.keys(this.record).length === 0 ||
        this.record.success === false
      ) {
        this.hideLoading();
        return;
      }
      this.handleReadOnly();
      this.handleDocLockSubscribe();
      // this.getSplitterValue();
      this.getSplitterValueFromStorage();
      this.handleDuplicateInvoiceSettings();

      if (this.isReadOnly) {
        this.error_message = this.$t('READ_ONLY_MSG');
        this.trigger_document_lock = false;
      } else {
        this.trigger_document_lock = true;
      }

      this.initPage();
    },
    setAppType() {
      if (!this.$route.params.id) {
        this.goToDashboard();
      }

      setTimeout(() => {
        this.showDialog = false;
      }, 10000);
    },
    async handleDuplicateInvoiceSettings() {
      await this.fetchAttributes(this.record.doc_type);
      this.isInvoiceDuplicate = this.model[CONSTANTS.DUPLICATE_DETECTION];
      if (!this.isInvoiceDuplicate) {
        this.isInvoiceDuplicate =
          this.model[CONSTANTS.DUPLICATE_INVOICE_DETECTION];
      }
    },
    setInvoiceDuplicateStatus(status: boolean) {
      this.isInvoiceDuplicate = status;
    },
    handleDocLockSubscribe() {
      const doc_lock_store = useDocLockStore();
      doc_lock_store.$subscribe((mutation, state) => {
        this.isReadOnly = !this.doc_lock?.success;
        this.handleReadOnly();
      });
    },
    handleReadOnly() {
      if (readOnlyDocStatus.includes(this.record.status)) {
        this.isReadOnly = true;
        return;
      }

      // check for access - pass the document to check permissions based on doc_type
      if (!Acl.canUpdate(this.record)) {
        this.isReadOnly = true;
      }
    },

    async getInvoiceDataByDocId(docId: string) {
      try {
        if (
          this.get_cached_data_id === docId &&
          (await this.setRecordFromCache())
        ) {
          return;
        }

        // this.showLoading();
        this.record = [];
        this.clearSelectedSessionStorage();
        await this.getDocumentById(docId);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        // this.hideLoading();
      }
    },
    getConfidence(confidence: number) {
      if (confidence) {
        return confidence < 1
          ? (+confidence.toFixed(2) * 100).toFixed(0)
          : +confidence.toFixed(2);
      }
      return '';
    },
    getLowerConfidence(field: any) {
      if (field.confidence && field.score) {
        let converted_confidence =
          field.confidence < 1
            ? (field.confidence.toFixed(2) * 100).toFixed(0)
            : (field.confidence.toFixed(2) as number);
        let converted_score =
          field.score <= 1
            ? (field.score.toFixed(2) * 100).toFixed(0)
            : (field.score.toFixed(2) as number);
        converted_confidence = Number(converted_confidence);
        converted_score = Math.floor(Number(converted_score));
        return converted_confidence < converted_score
          ? converted_confidence
          : converted_score;
      } else if (field.confidence) {
        return (
          field.confidence < 1
            ? (field.confidence.toFixed(2) * 100).toFixed(0)
            : field.confidence.toFixed(2)
        ) as number;
      }
      return null;
    },
    initPage() {
      this.handleFormatWarning();

      this.docType = this.record.doc_type;
      this.docStatus = this.record?.status;

      const recordImages = Array.isArray(this.record?.images)
        ? this.record.images
        : [];
      if (recordImages.length === 0) {
        console.warn(
          'MediOrder initPage: No images available in record',
          'doc_id=' + (this.record?.doc_id || 'unknown'),
        );
        return;
      }

      let doc2_image_url = this.handleImageBaseURL(recordImages);
      if (doc2_image_url !== '') {
        this.baseUrl = doc2_image_url;
      }

      this.setImage();

      this.images = cleanUpImagesUrl(recordImages);

      this.setDocVersion();

      marquee = $('#marquee') as HTMLElement;
      screenshot = $('.screenshot') as HTMLElement;
      boxes = $('#boxes') as HTMLElement;
      if (marquee) {
        marquee.classList.add('hide');
      }
      // set the width of image
      let imageElm = $('#image_container') as HTMLElement;
      if (!imageElm) {
        return;
      }
      this.imageWidth = imageElm.offsetWidth;
      this.imageHeight = imageElm.offsetHeight;
      this.viewBox =
        '0 0 ' + String(this.imageWidth) + ' ' + String(this.imageHeight);

      // double click to select
      screenshot.addEventListener('dblclick', this.dblClickToSelect);

      screenshot.addEventListener('pointerdown', this.startDrag);

      window.addEventListener('keydown', this.keydownEvent);
      document.addEventListener(
        'removeSelectedAreaOnImage',
        this.removeSelectedAreaOnImage,
      );
      this.getAI_IndicatorData();
      // TODO why this was placed?
      // this.handleRectsElementsLoading();
      this.setShowAllButtonsPanel();
    },
    setShowAllButtonsPanel() {
      const buttonArea = $('#buttonArea') as HTMLElement;
      if (buttonArea.clientWidth >= 300) {
        this.showAllButtons = true;
      } else {
        this.showAllButtons = false;
      }
    },

    setImage() {
      if (
        this.record.hasOwnProperty('classification') &&
        this.record.classification.hasOwnProperty('classification_page')
      ) {
        this.page = this.record.classification.classification_page;
      }
      const recordImages = Array.isArray(this.record?.images)
        ? this.record.images
        : [];
      if (recordImages.length === 0) {
        console.warn(
          'MediOrder setImage: No images available in record',
          'doc_id=' + (this.record?.doc_id || 'unknown'),
        );
        return;
      }
      const pageIndex = Math.max(
        0,
        Math.min(this.page - 1, recordImages.length - 1),
      );
      if (!recordImages[pageIndex]?.path) {
        console.warn(
          'MediOrder setImage: Invalid image at page index',
          'pageIndex=' + pageIndex,
          'doc_id=' + (this.record?.doc_id || 'unknown'),
        );
        return;
      }
      this.image =
        this.baseUrl +
        '/' +
        cleanUpImagePath(recordImages[pageIndex].path);
    },

    async isElementLoaded(selector: string) {
      while (document.querySelector(selector) === null) {
        await new Promise((resolve) => requestAnimationFrame(resolve));
      }
      return document.querySelector(selector);
    },

    handleRectsElementsLoading() {
      const data: any = this.record;
      this.fields_pending_load_count = 0;
      this.fields_loaded_count = 0;
      Array.from(data.fields).forEach((field: any) => {
        if (this.page == field.page && field.coords) {
          this.fields_pending_load_count++;

          this.isElementLoaded('#' + field.name).then((selector) => {
            this.fields_loaded_count++;
            if (this.fields_loaded_count == this.fields_pending_load_count) {
              this.prepareRectangles();
            }
          });
        }
      });
    },

    keydownEvent(e: any) {
      try {
        if (e.key === 'Escape') {
          this.removeBordersFromRectangles();
          this.removeAllConnectionLines();
          this.removeExistingConfirmationOverlays();
          this.restrictDrawing();
          this.removeMagnifier();
          this.isInvoiceDuplicate = false;
        } else if (e.key === 'Enter') {
          this.removeExistingConfirmationOverlays();
          this.removeBordersFromRectangles();
          this.removeAllConnectionLines();

          // setTimeout(() => {
          //   this.enableOrDisableExportButton();
          // }, 5);
          this.connectionId = '';
        } else if (e.key === 'ArrowDown') {
          this.removeExistingConfirmationOverlays();
          this.removeBordersFromRectangles();
          this.removeAllConnectionLines();
          (this.$refs['mediFieldsView'] as any).selectNextField(
            this.connectionId,
          );
          // setTimeout(() => {
          // this.enableOrDisableExportButton();
          // }, 5);
          this.connectionId = '';
        }
      } catch (e) {
        logInfo(e);
      }
    },

    async getAI_IndicatorData() {
      try {
        this.ai_fields =
          this.record && this.record.fields && Array.isArray(this.record.fields)
            ? this.record.fields.length
            : 0;

        let response: any;
        if (
          !this.record.filter_values ||
          !(this.record.filter_values.length > 0) ||
          !Array.isArray(this.record.filter_values)
        ) {
          throw 'getAI_IndicatorData () no filter_values or doc_type to proceed';
        }

        let query =
          '?doc_type=' +
          this.record.doc_type +
          '&filter_values=' +
          this.record.filter_values.join();

        response = await documentDetailApiService.get_ai_score(query);

        if (!response.success) {
          throw response.message;
        }

        if (response.success === true) {
          this.ai_rules = response.rules;
          const event = new CustomEvent('FV_gauge_calculation', {
            detail: response,
          });
          document.dispatchEvent(event);
        }
      } catch (err) {
        logError(err);
      }
    },
    imageclicked(evt: any) {
      this.connectionId = '';
      this.removeBordersFromRectangles();
      this.removeAllConnectionLines();
      this.removeExistingConfirmationOverlays();
      this.image =
        this.baseUrl +
        '/' +
        cleanUpImagePath(this.record.images[evt.target.dataset.id].path);

      this.getImageDetails();
      this.page = parseInt(evt.target.dataset.id) + 1;
    },

    async goToLineItems() {
      await this.setDataToCache();
      this.$router.push('/tbl_ext_v3/' + this.$route.params.id);
    },
    landing() {
      this.removeCache();
      this.$router.push('/land');
    },
    startDrag(ev: any) {
      let height = 0;
      let width = 0;
      if (ev.button === 1) {
        const rect = this.hitTest(ev.layerX, ev.layerY);
        if (rect) {
          rectangles.splice(rectangles.indexOf(rect), 1);
          this.redraw();
        }
        return;
      }
      window.addEventListener('pointerup', this.stopDrag);
      screenshot.addEventListener('pointermove', this.moveDrag);
      marquee.classList.remove('hide');
      startX = ev.layerX;
      startY = ev.layerY;
      let connectionId = '';
      Object.assign(marqueeRect, {
        startX,
        startY,
        width,
        height,
        connectionId,
      });
      this.drawRect(marquee, marqueeRect);
    },
    stopDrag(ev: any) {
      marquee.classList.add('hide');
      window.removeEventListener('pointerup', this.stopDrag);
      screenshot.removeEventListener('pointermove', this.moveDrag); //.bind(this)
      //  ev.target.removeEventListener('pointerup', this.stopDrag.bind(this));
      //  ev.target.removeEventListener('pointermove', this.moveDrag.bind(this));//.bind(this)
      if (ev.target === screenshot && marqueeRect.width && marqueeRect.height) {
        if (this.connectionId) {
          marqueeRect.connectionId = this.connectionId;
        }
        rectangles.push(Object.assign({}, marqueeRect));
        this.redraw();
        this.restrictDrawing();
        this.saveOverlayResult();
      }
    },
    moveDrag(ev: any) {
      let x = ev.layerX;
      let y = ev.layerY;
      let endX = ev.layerX;
      let endY = ev.layerY;
      let width = startX - x;
      let height = startY - y;
      if (width < 0) {
        width *= -1;
        x -= width;
      }
      if (height < 0) {
        height *= -1;
        y -= height;
      }
      let connectionId = '';
      Object.assign(rectCordinate, { startX, startY, endX, endY });
      Object.assign(marqueeRect, { x, y, width, height, connectionId });
      this.drawRect(marquee, marqueeRect);
    },
    hitTest(x: number, y: number) {
      return rectangles.find(
        (rect) =>
          x >= rect.x &&
          y >= rect.y &&
          x <= rect.x + rect.width &&
          y <= rect.y + rect.height,
      );
    },
    redraw() {
      if (!boxes) {
        return;
      }
      boxes.innerHTML = '';
      rectangles.forEach((data: any) => {
        boxes.appendChild(
          this.drawRect(
            document.createElementNS('http://www.w3.org/2000/svg', 'rect'),
            data,
          ),
        );
      });
    },
    drawRect(rect: any, data: any): any {
      if (typeof data == 'object') {
        let classes = 'cursor-pointer';

        const { x, y, width, height, connectionId } = data;
        rect.setAttributeNS(null, 'width', width);
        rect.setAttributeNS(null, 'height', height);
        rect.setAttributeNS(null, 'x', x);
        rect.setAttributeNS(null, 'y', y);
        rect.setAttributeNS(null, 'connectionId', connectionId);

        if (connectionId) {
          rect.setAttributeNS(null, 'id', connectionId + '_rect');

          let fieldArr = Array.isArray(this.record?.fields)
            ? this.record.fields.filter(
                (field: any) => connectionId == field.name,
              )
            : [];
          const field = fieldArr.length > 0 ? fieldArr.pop() : {};

          // Add class for TRocr field
          if (
            field.hasOwnProperty('trocr_processor') &&
            field.trocr_processor != ''
          ) {
            classes += ' extract_by_tcocr ';
          }
        }
        rect.setAttributeNS(null, 'class', classes);

        if (this.isReadOnly === false) {
          rect.addEventListener('click', this.showConnectionFromRect);
        }
      }
      return rect;
    },
    async getImageDetails() {
      // if image or fields are not loaded return
      if (this.renderComponent == false || this.imageLoaded == false) {
        return;
      }
      if (!screenshot) {
        return;
      }
      this.imageWidth = screenshot.offsetWidth;
      this.imageHeight = screenshot.offsetHeight;
      this.viewBox =
        '0 0 ' + String(this.imageWidth) + ' ' + String(this.imageHeight);
      //  this.assignImageDimenions();

      await this.$nextTick();
      this.prepareRectangles();

      if (!this.connectionId) {
        return;
      }

      if (this.isFreshStart) {
        // will be triggered when page is complete loading
        this.isFreshStart = false;
        this.showConnectionFromField(this.connectionId);
        return;
      }
      // will work for page change case
      let fieldElement: HTMLElement = this.getElementToConnect(
        $('#' + this.connectionId) as HTMLElement,
      ) as HTMLElement;
      if (!fieldElement) {
        return;
      }
      this.proceedForReactFinding(this.connectionId, fieldElement);

      //remove the loader after image is loaded completed
      // this.hideLoading();
      // this.enableOrDisableExportButton();
    },
    assignImageDimenions() {
      let imageElm = $('#image_container') as HTMLElement;
      if (imageElm) {
        this.imageWidth = imageElm.offsetWidth - 12;
        this.imageHeight = imageElm.offsetHeight - 32;
      }
      this.viewBox =
        '0 0 ' + String(this.imageWidth) + ' ' + String(this.imageHeight);
    },

    onFieldLoad(connectionId: string, isFreshStart: boolean) {
      this.connectionId = connectionId;
      this.isFreshStart = isFreshStart;
      this.getImageDetails();
    },

    prepareRectangles() {
      const data: any = this.record;
      rectangles = [];
      if (!Array.isArray(data?.fields)) {
        this.redraw();
        return;
      }
      Array.from(data.fields).forEach((field: any) => {
        const fieldObj: HTMLElement | null = $('#' + field.name);
        if (fieldObj) {
          if (this.page == field.page) {
            if (
              field.coords &&
              field.coords[0] &&
              field.coords[0].hasOwnProperty('x') &&
              field.coords[0].hasOwnProperty('y')
            ) {
              let startX = Math.round(this.imageWidth * field.coords[0].x);
              let startY = Math.round(this.imageHeight * field.coords[0].y);
              let endX = Math.round(this.imageWidth * field.coords[2].x);
              let endY = Math.round(this.imageHeight * field.coords[2].y);

              let width = endX - startX || 20;
              let height = endY - startY || 20;

              if (width < 0) {
                width *= -1;
                startX -= width;
              }
              if (height < 0) {
                height *= -1;
                startY -= height;
              }

              marqueeRect.x = startX;
              marqueeRect.y = startY;
              marqueeRect.width = width;
              marqueeRect.height = height;
              marqueeRect.connectionId = field.name;

              rectangles.push(Object.assign({}, marqueeRect));
            }
          }

          if (field.page && field.page != null) {
            fieldObj.setAttribute('pageno', field.page);
          }
        }
      });
      this.redraw();
    },
    showConnectionFromRect(ev: any) {
      // this.connectionId = '';
      this.removeBordersFromRectangles();
      this.removeAllConnectionLines();
      this.removeExistingConfirmationOverlays();
      this.restrictDrawing();
      const connectionId: string = ev.target.getAttribute('connectionId');
      const rectElement = ev.target;
      const fieldElement = this.getElementToConnect(
        $('#' + connectionId) as HTMLElement,
      );
      this.scrollInToViewCenter(fieldElement as HTMLElement);
      this.scrollInToViewCenter(rectElement);
      document.documentElement.scrollTop = 0;

      setTimeout(() => {
        this.showConnection(connectionId, rectElement, fieldElement);
      }, 50);
    },
    removeOverlayandLines() {
      this.removeBordersFromRectangles();
      this.removeAllConnectionLines();
      this.removeExistingConfirmationOverlays();
    },
    loadPageHavingReact(connectionId: string) {
      let fieldElement: HTMLElement = this.getElementToConnect(
        $('#' + connectionId) as HTMLElement,
      ) as HTMLElement;
      if (!fieldElement) {
        return;
      }
      let pageNumber = Number(fieldElement.getAttribute('pageno'));
      pageNumber = isNaN(pageNumber) ? this.page : pageNumber;
      const pageNumberChanged = pageNumber && pageNumber !== this.page;

      // Set the connection ID for highlighting
      this.connectionId = connectionId;

      // Set the new page and image URL if the page number has changed
      if (pageNumberChanged) {
        this.page = pageNumber;

        this.image =
          this.baseUrl +
          '/' +
          cleanUpImagePath(this.record.images[this.page - 1].path);
        return;
      }

      return fieldElement;
    },
    showConnectionFromField(connectionId: string) {
      this.removeOverlayandLines();
      this.restrictDrawing();

      let fieldElement: HTMLElement | undefined =
        this.loadPageHavingReact(connectionId);

      if (!fieldElement) {
        return;
      }

      this.proceedForReactFinding(connectionId, fieldElement);
    },
    proceedForReactFinding(connectionId: string, fieldElement: Element) {
      let rectElement = $('#' + connectionId + '_rect');

      if (rectElement) {
        this.scrollInToViewCenter(rectElement as HTMLElement);
        document.documentElement.scrollTop = 0;
      }

      setTimeout(() => {
        if (!rectElement) {
          this.proceedIfReactNotFound(fieldElement);
          return;
        }
        this.showConnection(connectionId, rectElement, fieldElement);
        this.connectionId = '';
      }, 50);
    },
    proceedIfReactNotFound(fieldElement: Element) {
      if (this.record.extraction_method === 'ELECTRONIC_DOCUMENT') {
        return;
      }
      this.componentType = fieldElement.getAttribute('child_type') as string;

      let inputValue = '';

      if (this.componentType === 'checkbox') {
        inputValue = fieldElement.getAttribute('aria-checked') ? 'true' : '';
      } else {
        let input: HTMLInputElement | null = fieldElement.querySelector(
          this.componentType,
        );

        if (input) {
          inputValue = input.value;
        }
      }

      if (inputValue != '') {
        this.showNotification(
          this.$t('SELECT_AREA_NO_COORDINATES'),
        );
        const message_event = new CustomEvent('dispatch_status_bar_message', {
          detail: { message: this.$t('SELECT_AREA') },
        });
        document.dispatchEvent(message_event);
      } else {
        this.showNotification(this.$t('SELECT_AREA'));
        const message_event = new CustomEvent('dispatch_status_bar_message', {
          detail: { message: this.$t('SELECT_AREA') },
        });
        document.dispatchEvent(message_event);
      }
      this.enableDrawing();
    },
    /**
     * This connection line will perform three tasks
     * 1. Add border to rect, but we'll remove previous border first
     * 2. Add line from input to rect, but we'll remove previous line first
     * 3. Add an overlay to rect to decide whether co-ordinates are correct or not
     * @param ev
     */
    showConnection(connectionId: string, rectElement: any, fieldElement: any) {
      if (rectElement && fieldElement) {
        this.drawOverlay(connectionId, rectElement);
        // Adding border to corresponding rectangle
        rectElement.classList.add('svg-stroke-border');

        // Drawling line
        this.connect(
          rectElement as HTMLElement,
          fieldElement as HTMLElement,
          '#26a69a',
          2,
        );
      } else {
        alert(this.$t('NO_MAPPING_AVAILABLE'));
      }
    },
    drawOverlay(connectionId: string, rectElement: any) {
      if (this.isConfirmationBoxDisable) {
        return;
      }

      this.connectionId = connectionId;
      this.removeExistingConfirmationOverlays();
      // parentDiv is the parent div of input that holds value
      // In order to get that value, we need to hit parent first
      // from parent, we'll get value of input
      const parentDiv: HTMLElement | null = $('#' + connectionId);
      if (!parentDiv) {
        return;
      }
      this.componentType = parentDiv.getAttribute('child_type') as string;
      // Getting input value
      let heading: string | null;

      let subHeading = '';

      if (this.componentType === 'checkbox') {
        // input = parentDiv.querySelector('.q-checkbox__bg');
        // let value = input!.getAttribute('aria-checked');
        subHeading = parentDiv.getAttribute('aria-label') as string;

        heading = 'Un-Checked';
        if (parentDiv.getAttribute('aria-checked') === 'true') {
          heading = 'Checked';
        }
      } else {
        const parentDivHeading: Element | null = $('.' + connectionId);
        subHeading = parentDivHeading!.innerHTML;

        const input: HTMLInputElement | null = parentDiv.querySelector(
          this.componentType,
        );
        heading = input!.value;
      }

      // const input: HTMLInputElement | null = parentDiv.querySelector( this.componentType );

      // Getting input label

      // const width = ev.target.getAttribute('width');
      const dimensionDetails = this.getOffset(rectElement);

      const divOverlay = document.createElement('div');
      divOverlay.setAttribute('id', 'confirmation_overlay');
      divOverlay.style.position = 'absolute';
      divOverlay.style.zIndex = '99999';
      divOverlay.style.left = dimensionDetails.left + 'px';
      divOverlay.style.top =
        (+dimensionDetails.top + +dimensionDetails.height + 6).toString() +
        'px';
      divOverlay.style.background = '#e2e2e2';
      divOverlay.style.color = '#898989';
