      getDocumentById,
      setRecordFromCache,
      setDataToCache,
      removeCache,
      resetDocStore,
    } = doc_store;

    const form_builder_store = useFormBuilderStore();

    const { formLayout, isExtenedPanel, renderComponent, docType, layout_template_id } =
      storeToRefs(form_builder_store);
    const { getElementWidth, isFieldHidden } = form_builder_store;

    let fieldsObjArray: any = {};
